files.content:
.root {
  --vt-surface: #FFFFFF;
  --vt-surface-2: #F9F9F9;
  --vt-surface-deep: #eaeaea;
  --vt-ink: #000000;
  --vt-ink-soft: #717275;
  --vt-on-deep: #565758;
  --vt-accent: #247cff;
  --vt-on-accent: #FFFFFF;
  --vt-accent-ink: #247cff;
  --vt-accent-on-deep: #1a4d8f;
  --vt-line: #eaeaea;

  --body-font-family: 'Open Sans', sans-serif;

  font-family: var(--body-font-family);
  color: var(--vt-ink-soft);
  background: var(--vt-surface);
  line-height: 1.5;
  overflow-x: hidden;
}

.root h1,
.root h2,
.root h3,
.root h4,
.root h5,
.root h6 {
  color: var(--vt-ink);
  line-height: 1.2;
  font-weight: 700;
}

.root h1 {
  font-size: 48px;
  margin: 0 0 0.5rem;
}

.root h2 {
  font-size: 36px;
  margin: 0 0 1rem;
}

.root h3 {
  font-size: 32px;
}

.root h5 {
  font-size: 24px;
  margin: 0 0 1rem;
}

.root p {
  color: var(--vt-ink-soft);
  font-size: 18px;
  font-weight: 300;
  letter-spacing: 0.5px;
  margin: 0 0 1rem;
}

.root a {
  color: var(--vt-ink-soft);
  text-decoration: none;
  transition: color 0.3s;
}

.root a:hover {
  color: var(--vt-accent);
}

.root a:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 2px;
}

/* Navigation */
.nav {
  background: var(--vt-surface);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
  padding: 20px 0;
  position: relative;
  z-index: 10;
}

.navIn {
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.navGroup {
  display: flex;
  gap: 30px;
}

.navLink {
  color: var(--vt-ink-soft);
  font-weight: 600;
  font-size: 16px;
  padding: 5px 0;
}

.logo {
  text-decoration: none;
  margin: 0 30px;
}

.brand {
  color: var(--vt-accent);
  font-size: 24px;
  font-weight: 700;
  text-align: center;
  display: block;
}

.brand strong {
  color: var(--vt-ink-soft);
  font-size: 12px;
  font-weight: 400;
  display: block;
  position: relative;
  bottom: 5px;
}

/* Hero */
.hero {
  position: relative;
  height: 580px;
  overflow: hidden;
}

.heroTrack {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  height: 100%;
}

.heroSlide {
  flex: 0 0 100%;
  scroll-snap-align: start;
}

.heroSlide img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.heroCard {
  position: absolute;
  bottom: 0;
  right: 0;
  background: var(--vt-surface);
  padding: 1.5rem 2.5rem;
  width: 50%;
  box-shadow: 0 0 15px rgba(0, 0, 0, 0.1);
}

.heroTitle {
  color: var(--vt-ink);
  font-size: 48px;
  line-height: 1.2;
  margin-bottom: 0.5rem;
}

.heroText {
  color: var(--vt-ink-soft);
  margin-bottom: 1rem;
}

.heroLinks {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
}

.customLink {
  display: inline-block;
  border: 1px solid var(--vt-line);
  color: var(--vt-accent);
  font-weight: 600;
  line-height: 40px;
  padding: 0 30px;
  margin-right: 1.5rem;
  text-transform: uppercase;
  position: relative;
  overflow: hidden;
  transition: all 0.3s;
}

.customLink::before {
  content: attr(data-hover);
  background: var(--vt-line);
  color: var(--vt-accent);
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  text-align: center;
  transition: top 0.3s cubic-bezier(0.19, 1, 0.56, 1);
}

.customLink:hover::before {
  top: 0;
}

.contactPhone {
  font-weight: 600;
  color: var(--vt-ink-soft);
  margin: 0;
}

.contactPhone i {
  margin-right: 5px;
}

/* Sections common */
.container {
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
}

.sectionTitle {
  text-align: center;
  margin-bottom: 2rem;
}

.sectionText {
  text-align: center;
  max-width: 800px;
  margin: 0 auto 2rem;
}

/* About */
.about {
  padding: 7rem 0;
}

/* Gallery */
.gallery {
  padding: 0;
}

.galleryGrid {
  display: flex;
  flex-wrap: wrap;
}

.galleryItem {
  width: 50%;
  margin: 0;
}

.galleryItem img {
  width: 100%;
  height: auto;
  display: block;
}

/* Timeline */
.timeline {
  padding: 7rem 0 0;
}

.timelineGrid {
  position: relative;
  padding: 2rem 0;
}

.timelineGrid::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: 50%;
  width: 1px;
  background: var(--vt-line);
  transform: translateX(-50%);
}

.timelineNode {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 2rem;
  position: relative;
}

.even {
  flex-direction: row;
}

.odd {
  flex-direction: row-reverse;
}

.timelineIcon {
  width: 80px;
  height: 80px;
  background: var(--vt-surface);
  border-radius: 50%;
  box-shadow: 0 1rem 3rem rgba(0, 0, 0, 0.175);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  z-index: 100;
}

.timelineIcon span {
  color: var(--vt-accent-on-deep);
  font-size: 32px;
  font-weight: 300;
}

.timelineContent {
  width: 45%;
  background: var(--vt-surface);
  box-shadow: 0 0 15px rgba(0, 0, 0, 0.1);
  border-radius: 0 0 4px 4px;
  position: relative;
}

.timelineHeading {
  background: var(--vt-ink);
  color: var(--vt-on-accent);
  padding: 10px 30px;
  font-size: 24px;
  position: relative;
  border-radius: 4px 4px 0 0;
}

.timelineNode.odd .timelineHeading::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 100%;
  transform: translateY(-50%);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
  border-left: 10px solid var(--vt-ink);
}

.timelineNode.even .timelineHeading::after {
  content: "";
  position: absolute;
  top: 50%;
  right: 100%;
  transform: translateY(-50%);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
  border-right: 10px solid var(--vt-ink);
}

.timelineText {
  padding: 10px 30px;
  color: var(--vt-ink-soft);
  margin: 0;
}

/* Footer */
.footer {
  background: var(--vt-surface-2);
  padding: 7rem 0;
}

.footerGrid {
  display: flex;
  gap: 30px;
  justify-content: space-between;
}

.footerCol {
  flex: 1 1 0;
}

.footerHeading {
  color: var(--vt-ink);
  margin-bottom: 1rem;
}

.socialLinks {
  display: flex;
  gap: 15px;
}

.copyright {
  text-align: center;
  margin-top: 2rem;
}

.copyright p {
  font-size: 16px;
}

/* Responsive */
@media (max-width: 991px) {
  .root h1 {
    font-size: 38px;
  }
  .root h2 {
    font-size: 32px;
  }
  .root h3 {
    font-size: 26px;
  }
  .root h5 {
    font-size: 20px;
  }
  .about,
  .gallery,
  .timeline,
  .footer {
    padding-top: 5rem;
    padding-bottom: 5rem;
  }
  .timeline {
    padding-bottom: 0;
  }
  .hero {
    height: auto;
  }
  .heroTrack {
    height: auto;
  }
  .heroSlide img {
    height: auto;
  }
  .heroCard {
    position: relative;
    bottom: auto;
    right: auto;
    width: auto;
    margin-bottom: -100px;
    padding: 2rem;
  }
  .navIn {
    flex-wrap: wrap;
  }
  .navGroup {
    gap: 20px;
  }
  .logo {
    margin: 0 20px;
  }
  .footerGrid {
    flex-wrap: wrap;
  }
  .footerCol {
    flex-basis: 45%;
  }
}

@media (max-width: 767px) {
  .heroCard {
    padding: 1.5rem;
    margin-bottom: -80px;
  }
  .galleryItem {
    width: 100%;
  }
  .timelineGrid::before {
    left: 33px;
  }
  .timelineNode {
    flex-direction: column;
    align-items: flex-start;
    padding-left: 60px;
    position: relative;
  }
  .timelineIcon {
    position: absolute;
    left: 0;
    top: 0;
    width: 60px;
    height: 60px;
  }
  .timelineIcon span {
    font-size: 24px;
  }
  .timelineContent {
    width: 100%;
    margin-left: 0;
  }
  .timelineNode.odd .timelineHeading::after,
  .timelineNode.even .timelineHeading::after {
    display: none;
  }
  .footerCol {
    flex-basis: 100%;
  }
}

@media (max-width: 575px) {
  .timelineGrid::before {
    left: 27px;
  }
  .timelineNode {
    padding-left: 50px;
  }
  .timelineIcon {
    width: 50px;
    height: 50px;
  }
  .timelineIcon span {
    font-size: 20px;
  }
}

@media (max-width: 480px) {
  .heroCard {
    padding: 1rem;
  }
  .customLink {
    font-size: 12px;
    line-height: 30px;
    padding: 0 20px;
    margin-right: 12px;
  }
  .contactPhone {
    font-size: 12px;
  }
}

@media (max-width: 360px) {
  .brand {
    font-size: 20px;
  }
  .timelineGrid::before {
    left: 22px;
  }
  .timelineNode {
    padding-left: 40px;
  }
  .timelineIcon {
    width: 40px;
    height: 40px;
  }
  .timelineIcon span {
    font-size: 16px;
  }
}
